function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'FileSystem' || args[0].length !== 0) return 'Start with FileSystem and no arguments.';
  if (operations.length - 1 > 300) return 'At most 300 calls after the constructor.';
  const shape = /^\/$|^(\/[a-z]+)+$/;
  const kind = new Map([['/', 'dir']]);
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    if (!['ls', 'mkdir', 'addContentToFile', 'readContentFromFile'].includes(op)) return `Call ${i}: unknown operation ${op}.`;
    const count = op === 'addContentToFile' ? 2 : 1;
    if (!Array.isArray(args[i]) || args[i].length !== count) return `Call ${i}: ${op} takes ${count} argument${count > 1 ? 's' : ''}.`;
    const [path, content] = args[i];
    if (typeof path !== 'string' || path.length > 100 || !shape.test(path)) return `Call ${i}: a path starts with / and joins lowercase names with /, in at most 100 characters.`;
    if (op === 'ls' && !kind.has(path)) return `Call ${i}: ls needs a path that exists.`;
    if (op === 'readContentFromFile' && kind.get(path) !== 'file') return `Call ${i}: readContentFromFile needs an existing file.`;
    if (op === 'mkdir') {
      if (kind.has(path)) return `Call ${i}: mkdir needs a path that does not exist yet.`;
      let prefix = '';
      for (const part of path.split('/').slice(1)) {
        prefix += '/' + part;
        if (kind.get(prefix) === 'file') return `Call ${i}: mkdir cannot go below a file.`;
        kind.set(prefix, 'dir');
      }
    }
    if (op === 'addContentToFile') {
      if (typeof content !== 'string' || content.length < 1 || content.length > 50) return `Call ${i}: content needs 1 to 50 characters.`;
      if (path === '/' || kind.get(path) === 'dir') return `Call ${i}: addContentToFile needs a file path, not a directory.`;
      if (kind.get(path.slice(0, path.lastIndexOf('/')) || '/') !== 'dir') return `Call ${i}: the file's directory must already exist.`;
      kind.set(path, 'file');
    }
  }
  return null;
}

