class FileSystem {
  constructor() {
    this.entries = new Map([['/', { isFile: false, content: '' }]]);
  }
  ls(path) {
    const entry = this.entries.get(path);
    if (entry.isFile) return [path.split('/').pop()];
    const prefix = path === '/' ? '/' : path + '/';
    const names = [];
    for (const key of this.entries.keys()) {
      if (key === '/' || !key.startsWith(prefix)) continue;
      const rest = key.slice(prefix.length);
      if (!rest.includes('/')) names.push(rest);
    }
    return names.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  }
  mkdir(path) {
    const parts = path.split('/');
    for (let end = 2; end <= parts.length; end++) {
      const prefix = parts.slice(0, end).join('/');
      if (!this.entries.has(prefix)) this.entries.set(prefix, { isFile: false, content: '' });
    }
  }
  addContentToFile(filePath, content) {
    const entry = this.entries.get(filePath);
    if (entry) entry.content = entry.content + content;
    else this.entries.set(filePath, { isFile: true, content });
  }
  readContentFromFile(filePath) {
    return this.entries.get(filePath).content;
  }
}

