function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = size === 'large' ? ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'doc', 'src', 'lib', 'bin', 'tmp', 'x', 'y', 'zz'] : ['a', 'b', 'c', 'ab'];
  const join = (dir, name) => (dir === '/' ? '/' + name : dir + '/' + name);
  const word = () => {
    let text = '';
    const length = 1 + Math.floor(rand() * (size === 'large' ? 50 : 4));
    for (let k = 0; k < length; k++) text += 'abcdexyz'[Math.floor(rand() * 8)];
    return text;
  };
  const kind = new Map([['/', 'dir']]);
  const dirs = ['/'], files = [];
  const operations = ['FileSystem'], args = [[]];
  const calls = size === 'large' ? 300 : 1 + Math.floor(rand() * 12);
  while (operations.length - 1 < calls) {
    const roll = rand();
    if (roll < 0.3) {
      let path = pick(dirs), blocked = false;
      const depth = 1 + Math.floor(rand() * 3);
      for (let k = 0; k < depth && !blocked; k++) {
        path = join(path, pick(names));
        if (kind.get(path) === 'file') blocked = true;
      }
      if (blocked || kind.has(path) || path.length > 100) continue;
      let prefix = '';
      for (const part of path.split('/').slice(1)) {
        prefix += '/' + part;
        if (!kind.has(prefix)) { kind.set(prefix, 'dir'); dirs.push(prefix); }
      }
      operations.push('mkdir'); args.push([path]);
    } else if (roll < 0.55) {
      const path = files.length && rand() < 0.3 ? pick(files) : join(pick(dirs), pick(names));
      if (kind.get(path) === 'dir' || path.length > 100) continue;
      if (!kind.has(path)) { kind.set(path, 'file'); files.push(path); }
      operations.push('addContentToFile'); args.push([path, word()]);
    } else if (roll < 0.85) {
      operations.push('ls'); args.push([files.length && rand() < 0.25 ? pick(files) : pick(dirs)]);
    } else if (files.length) {
      operations.push('readContentFromFile'); args.push([pick(files)]);
    }
  }
  return [operations, args];
}
